/* The same source runs in Cockpit and as an offline, localStorage-backed demo. */
(function () {
  'use strict';
  const $ = (s, root = document) => root.querySelector(s);
  const esc = (v) => String(v == null ? '' : v).replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const now = () => new Date().toISOString();
  const fmt = v => v ? new Date(v).toLocaleString() : '—';
  const stateKey = 'pro6000d-training-demo-v2';
  const isCockpit = !!window.cockpit;
  let page = 'training', tab = 'queue', state = null, demoRole = null, toastTimer = null;

  const defaultDemo = () => ({
    identity: {uid: 1001, username: 'timzhang', is_admin: false, is_training_user: true},
    scheduler_available: false,
    observed_at: now(),
    quota: {gpu_limit: 2, concurrent_gpu_limit: 2, active_job_limit: 2, source: 'default'},
    rules: {debug:{max_minutes:60}, normal:{max_minutes:1440}, long:{max_minutes:4320}},
    gpus: {available:true, demo:true, ownership:'stable_demo_ids', devices:[
      {index:'0',id:'demo-gpu-0',name:'演示 GPU 0',memory_total_mb:'24564',memory_used_mb:'0',utilization_percent:'0',owner_job_id:null},
      {index:'1',id:'demo-gpu-1',name:'演示 GPU 1',memory_total_mb:'24564',memory_used_mb:'0',utilization_percent:'0',owner_job_id:null}
    ]},
    metrics: {available:true,demo:true,observed_at:now(),cpu_load_1m:0.18,memory_total_mb:32768,memory_available_mb:24576,gpu:{available:true}},
    jobs: [
      {id:'demo-8128',scheduler_id:'8128',owner_uid:1001,owner_name:'timzhang',name:'resnet-debug',state:'RUNNING',requested_gpu:1,requested_cpu:8,requested_mem_mb:32768,requested_minutes:60,qos:'debug',workdir:'/home/timzhang/train',env_name:'torch-env',command:'python train.py',output_path:'/home/timzhang/train/slurm-%j.out',reason_code:'running',reason_text:'调度器已启动',created_at:'2026-10-27T08:10:00Z',updated_at:now()},
      {id:'demo-8132',scheduler_id:'8132',owner_uid:1002,owner_name:'alice',name:'llm-long',state:'PENDING',requested_gpu:2,requested_cpu:16,requested_mem_mb:65536,requested_minutes:3000,qos:'long',workdir:'/home/alice/train',env_name:'system',command:'python train.py',output_path:'/home/alice/train/slurm-%j.out',reason_code:'machine_resources',reason_text:'请求资源暂时不可用，保持排队',created_at:'2026-10-27T08:28:00Z',updated_at:now()}
    ], applications: [], notifications: []
  });

  function loadDemo() {
    try { const raw = localStorage.getItem(stateKey); if (raw) return JSON.parse(raw); } catch (_) {}
    return defaultDemo();
  }
  function saveDemo() { if (!isCockpit) try { localStorage.setItem(stateKey, JSON.stringify(state)); } catch (_) {} }
  function api(method, path, body) {
    if (!isCockpit) return Promise.resolve(demoApi(method, path, body));
    return new Promise((resolve, reject) => {
      const proc = cockpit.spawn(['/usr/libexec/pro6000d-training-client'], {err: 'message'});
      let output = '';
      proc.stream(data => { output += data; });
      proc.input(JSON.stringify({method, path, body: body || {}}) + '\n');
      proc.then(() => { try { const response = JSON.parse(output.trim()); response.ok ? resolve(response.data) : reject(response.error); } catch (e) { reject({message:'无法解析后端响应'}); } });
      proc.catch(err => reject({message: String(err)}));
    });
  }
  function demoApi(method, path, body) {
    if (path === '/api/v1/me') return {identity:state.identity,version:'demo'};
    if (path === '/api/v1/state') return state;
    if (method === 'GET' && path === '/api/v1/jobs') return {jobs:state.jobs};
    if (method === 'GET' && path === '/api/v1/applications') return {applications:state.applications};
    if (method === 'POST' && path === '/api/v1/jobs/validate') {
      const j = normalizeJob(body), u = usage(state.identity.username), q = state.quota;
      return {job:j,quota:q,usage:u};
    }
    if (method === 'POST' && path === '/api/v1/jobs') return demoSubmit(body);
    if (method === 'POST' && path === '/api/v1/applications') return {application:demoApplication(body)};
    if (method === 'POST' && path.includes('/decision')) return {application:demoDecision(path.split('/')[4], body)};
    if (method === 'POST' && path.includes('/cancel')) { const id=path.split('/')[4]; const j=state.jobs.find(x=>x.id===id); if(j){j.state='CANCELLED';j.reason_code='cancelled_by_user';j.reason_text='用户取消，未影响其他任务';saveDemo();} return {job:j}; }
    if (method === 'POST' && path.includes('/read')) { const id=path.split('/')[4]; const n=state.notifications.find(x=>x.id===id); if(n)n.read_at=now();saveDemo();return {ok:true}; }
    if (method === 'POST' && path === '/api/v1/rules/preview') return demoRulePreview(body.rules);
    if (method === 'POST' && path === '/api/v1/rules/apply') { state.rules=body.rules; saveDemo(); return {applied:true,impacts:[]}; }
    if (method === 'POST' && path === '/api/v1/quotas/preview') return demoQuotaPreview(body);
    if (method === 'POST' && path === '/api/v1/quotas/apply') { state.quota=body.quota; saveDemo(); return {applied:true,impacts:[]}; }
    return {};
  }
  function normalizeJob(p) { return {name:p.name||'training',command:p.command||'',qos:p.qos||'normal',gpu:+p.gpu||1,cpu:+p.cpu||1,memory_mb:+p.memory_mb||1024,time_minutes:+p.time_minutes||60,workdir:p.workdir||'',environment:p.environment||'system',output_path:p.output_path||''}; }
  function usage(username) { const a=state.jobs.filter(j=>j.owner_name===username&&['PENDING','RUNNING'].includes(j.state));return {gpu:a.reduce((n,j)=>n+j.requested_gpu,0),active_jobs:a.length,concurrent_gpu:a.reduce((n,j)=>n+j.requested_gpu,0)}; }
  function demoSubmit(p) {
    const j=normalizeJob(p), u=usage(state.identity.username), q=state.quota;
    if(j.gpu>q.gpu_limit) throw {code:'permanent_quota_exceeded',message:'单作业 GPU 请求超过本用户个人上限，可提交临时资源申请'};
    const fits=u.gpu+j.gpu<=q.gpu_limit&&u.active_jobs+1<=q.active_job_limit;
    const id='demo-'+Math.floor(Math.random()*9000+1000);
    const row={id,scheduler_id:null,owner_uid:state.identity.uid,owner_name:state.identity.username,name:j.name,state:fits?'PENDING':'WAITING_QUOTA',requested_gpu:j.gpu,requested_cpu:j.cpu,requested_mem_mb:j.memory_mb,requested_minutes:j.time_minutes,qos:j.qos,workdir:j.workdir,env_name:j.environment,command:j.command,output_path:j.output_path,reason_code:fits?'machine_resources':'waiting_user_quota',reason_text:fits?'演示调度器未连接，保持未提交状态':'当前用户额度已占用，额度释放后再入调度器',created_at:now(),updated_at:now()};
    state.jobs.unshift(row);saveDemo();return {job:row};
  }
  function demoApplication(p) { const a={id:'app-'+Math.random().toString(16).slice(2,10),owner_uid:state.identity.uid,owner_name:state.identity.username,kind:p.kind,status:p.kind==='temporary_job'?'DISABLED':'PENDING',requested:p.requested,reason:p.reason,created_at:now(),updated_at:now(),approved:null};state.applications.unshift(a);notifyAdmins(a);saveDemo();return a; }
  function notifyAdmins(a) { if(a.owner_name!=='u20') state.notifications.unshift({id:'n-'+Date.now(),kind:'application_pending',title:'有新的额度申请',body:a.owner_name+' 提交了申请',created_at:now(),read_at:null}); }
  function demoDecision(id,p) { const a=state.applications.find(x=>x.id===id);if(!a)throw{message:'申请不存在'};if(a.status!=='PENDING')throw{message:'终态申请不能重复操作'};if(p.action==='reject'&&!p.decision_reason)throw{message:'拒绝必须填写理由'};a.status=p.action==='reject'?'REJECTED':'APPROVED';a.approved=p.approved||a.requested;a.decision_reason=p.decision_reason||'管理员批准';a.updated_at=now();state.notifications.unshift({id:'n-'+Date.now(),kind:'application_decision',title:'申请已'+(a.status==='APPROVED'?'批准':'拒绝'),body:a.decision_reason,created_at:now(),read_at:null});saveDemo();return a; }
  function demoRulePreview(rules) { return {preview_id:'demo-rule-preview',before:{qos:state.rules},after:rules,impacts:state.jobs.filter(j=>['PENDING','RUNNING'].includes(j.state)&&j.requested_minutes>(rules[j.qos]||{}).max_minutes).map(j=>({job_id:j.id,scheduler_id:j.scheduler_id,user:j.owner_name,reasons:['单作业时限超过新档位上限'],action:'仅提示，不自动终止'}))}; }
  function demoQuotaPreview(p) { return {preview_id:'demo-quota-preview',before:state.quota,after:p.quota,impacts:[]}; }
  function failText(e) { return e && (e.message || e.code) || '操作失败'; }
  function showToast(message, kind='success') { const n=document.createElement('div');n.className='toast';n.textContent=message;document.body.appendChild(n);setTimeout(()=>n.remove(),4500); }
  function tag(text, kind='') { return `<span class="tag ${kind}">${esc(text)}</span>`; }
  function stateTag(s) { return tag({RUNNING:'运行中',PENDING:'调度排队',WAITING_QUOTA:'用户额度等待',CANCELLED:'已取消',COMPLETED:'已完成',FAILED:'失败',UNKNOWN:'状态未知',REJECTED:'已拒绝'}[s]||s, {RUNNING:'green',PENDING:'blue',WAITING_QUOTA:'amber',FAILED:'red',REJECTED:'red'}[s]||''); }
  function pageHead(title, subtitle, actions='') { return `<div class="pagehead"><div><h1>${title}</h1><div class="subtitle">${subtitle}</div></div><div class="actions">${actions}</div></div>`; }
  function banner() { const unavailable=!state.scheduler_available;return `<div class="banner ${unavailable?'warn':''}"><b>${unavailable?'演示/未连接':'实时后端'}</b> ${unavailable?'当前没有可用的 Slurm 调度器，页面不会伪造任务或固定资源数字。':'数据由受限后端读取；所有动作按当前 Cockpit UID校验。'} 最后更新时间：${fmt(state.observed_at)}。${state.gpus&&state.gpus.demo?' 当前为离线演示状态。':''}</div>`; }
  function render() {
    if(!state)return;
    $('#identity').textContent=state.identity.username+(state.identity.is_admin?' · 管理员':' · 普通用户');
    const unread=(state.notifications||[]).filter(n=>!n.read_at).length;$('#notification-count').textContent=unread;$('#notification-count').hidden=!unread;
    $('#connection').className='tag '+(state.scheduler_available?'green':'amber');$('#connection').textContent=state.scheduler_available?'后端已连接':'演示/调度器未连接';$('#host-state').textContent=state.scheduler_available?'Slurm 实时状态':'状态不可用/演示';$('#last-updated').textContent='最后更新 '+fmt(state.observed_at);
    document.querySelectorAll('.navitem').forEach(b=>b.classList.toggle('active',b.dataset.page===page));
    $('#applications-nav').textContent=state.identity.is_admin?'申请审批':'我的申请';
    const pages={overview:renderOverview,training:renderTraining,storage:renderStorage,accounts:renderAccounts,metrics:renderMetrics,logs:renderLogs,rules:renderRules,applications:renderApplications};$('#main').innerHTML=(pages[page]||renderTraining)();bind();
  }
  function renderOverview() { const running=state.jobs.filter(j=>j.state==='RUNNING').length,pending=state.jobs.filter(j=>['PENDING','WAITING_QUOTA'].includes(j.state)).length;return pageHead('概览','系统入口与训练资源共享同一状态')+banner()+`<div class="overview"><div class="stat"><div class="statlabel">运行任务</div><div class="statvalue">${running}</div><div class="statnote">从调度器状态读取</div></div><div class="stat"><div class="statlabel">排队任务</div><div class="statvalue">${pending}</div><div class="statnote">含用户额度等待</div></div><div class="stat"><div class="statlabel">GPU</div><div class="statvalue">${state.gpus.available?state.gpus.devices.length:'—'}</div><div class="statnote">设备探测结果</div></div><div class="stat"><div class="statlabel">调度器</div><div class="statvalue">${state.scheduler_available?'在线':'—'}</div><div class="statnote">不写入固定示例数值</div></div></div><div class="grid2"><div class="card"><div class="cardhead"><h2>GPU 设备</h2></div><div class="cardbody">${renderGpuCards()}</div></div><div class="card"><div class="cardhead"><h2>运行边界</h2></div><div class="cardbody"><p>作业以调用用户 UID 提交；管理员不能替用户执行命令。日志只从作业记录的用户目录读取，取消不会重新分配其他任务的设备。</p><div class="notice">详细系统概览、存储和日志继续使用原生 Cockpit；本插件只增加训练和调度页面。</div></div></div></div>`; }
  function renderGpuCards(){if(!state.gpus||!state.gpus.available)return `<div class="empty">GPU 数据不可用<br><span class="small">${esc(state.gpus&&state.gpus.reason||'等待后端采集')}</span></div>`;return `<div class="gpu-grid">${state.gpus.devices.map(g=>`<div class="gpu"><strong>GPU ${esc(g.index)}</strong> ${tag(esc(g.id),'blue')}<div class="owner">${g.owner_job_id?'Job '+esc(g.owner_job_id):'归属未从 Slurm GRES 映射'}</div><div class="meter"><span style="width:${Math.min(100,+g.utilization_percent||0)}%"></span></div><div class="small">${esc(g.name)} · ${esc(g.memory_used_mb)} / ${esc(g.memory_total_mb)} MiB · ${esc(g.utilization_percent)}%</div></div>`).join('')}</div>`;}
  function renderTraining(){const q=state.quota,u=usage(state.identity.username),actions=state.scheduler_available?`<button class="pf-c-button pf-m-primary" data-action="submit">提交训练</button>`:'';return pageHead('训练管理','队列、日志和我的申请',actions)+banner()+`<div class="overview"><div class="stat"><div class="statlabel">GPU 保留 / 上限</div><div class="statvalue">${u.gpu} / ${q.gpu_limit}</div><div class="statnote">跨所有 QoS</div></div><div class="stat"><div class="statlabel">并发 GPU / 上限</div><div class="statvalue">${u.concurrent_gpu} / ${q.concurrent_gpu_limit}</div><div class="statnote">后端调度闸门</div></div><div class="stat"><div class="statlabel">活动任务 / 上限</div><div class="statvalue">${u.active_jobs} / ${q.active_job_limit}</div><div class="statnote">排队和运行任务</div></div><div class="stat"><div class="statlabel">额度来源</div><div class="statvalue" style="font-size:18px">${q.source==='personal_override'?'个人覆盖':'默认额度'}</div><div class="statnote">账户页可查看</div></div></div><div class="panel"><div class="tabs"><button class="tab ${tab==='queue'?'active':''}" data-tab="queue">任务队列</button><button class="tab ${tab==='logs'?'active':''}" data-tab="logs">日志</button><button class="tab ${tab==='mine'?'active':''}" data-tab="mine">我的申请</button></div><div class="panelbody">${tab==='queue'?renderQueue():tab==='logs'?renderLogList():renderMyApplications()}</div></div>`;}
  function renderQueue(){if(!state.jobs.length)return '<div class="empty">暂无任务</div>';return `<div class="table-scroll"><table><thead><tr><th>JobID / 用户</th><th>状态与原因</th><th>资源</th><th>档位 / 时限</th><th>工作目录</th><th>操作</th></tr></thead><tbody>${state.jobs.map(j=>`<tr><td><span class="jobid">${esc(j.scheduler_id||j.id)}</span><div class="jobmeta">${esc(j.owner_name)} · ${esc(j.name)}</div></td><td>${stateTag(j.state)}<div class="reason">${esc(j.reason_text||'—')}</div></td><td>${j.requested_gpu} GPU / ${j.requested_cpu} CPU / ${j.requested_mem_mb} MiB</td><td>${esc(j.qos)}<div class="jobmeta">${j.requested_minutes} 分钟</div></td><td class="mono">${esc(j.workdir)}</td><td><button class="linkbutton" data-log="${esc(j.id)}">日志</button>${['PENDING','RUNNING','WAITING_QUOTA'].includes(j.state)?`<button class="linkbutton" data-cancel="${esc(j.id)}">取消</button>`:''}</td></tr>`).join('')}</tbody></table></div>`;}
  function renderLogList(){return `<div class="notice">日志访问由后端按作业 UID 和记录路径校验，并以作业用户权限读取，最多返回 1 MiB。${state.scheduler_available?'':' 当前没有真实调度器日志。'}</div>${state.jobs.map(j=>`<div style="padding:11px 0;border-bottom:1px solid #eee"><b>${esc(j.scheduler_id||j.id)}</b> · ${esc(j.owner_name)} <button class="linkbutton" data-log="${esc(j.id)}">打开日志</button><div class="small mono">${esc(j.output_path)}</div></div>`).join('')||'<div class="empty">暂无日志</div>'}`;}
  function renderMyApplications(){return renderApplicationTable((state.applications||[]).filter(a=>a.owner_uid===state.identity.uid));}
  function renderApplications(){return pageHead(state.identity.is_admin?'申请审批':'我的申请','批准不会挤掉现有任务；临时批准绑定一次性任务和有效期')+banner()+renderApplicationTable(state.applications||[]);}
  function renderApplicationTable(rows){return `<div class="toolbar">${!state.identity.is_admin?'<button class="pf-c-button pf-m-primary" data-action="apply-temp">申请临时资源</button><button class="pf-c-button pf-m-secondary" data-action="apply-quota">申请长期个人额度</button>':''}</div><div class="table-scroll"><table><thead><tr><th>申请</th><th>用户</th><th>状态</th><th>资源</th><th>理由 / 结果</th><th>时间</th><th>操作</th></tr></thead><tbody>${rows.map(a=>`<tr><td class="mono">${esc(a.id)}</td><td>${esc(a.owner_name)}</td><td>${tag({PENDING:'待审批',APPROVED:'已批准',REJECTED:'已拒绝',EXPIRED:'已过期',DISABLED:'暂未启用'}[a.status]||a.status,a.status==='APPROVED'?'green':a.status==='REJECTED'?'red':'amber')}</td><td class="mono">${esc(JSON.stringify(a.requested))}</td><td>${esc(a.reason)}<div class="jobmeta">${esc(a.decision_reason||'')}</div></td><td>${fmt(a.created_at)}</td><td>${state.identity.is_admin&&a.status==='PENDING'?`<button class="linkbutton" data-approve="${esc(a.id)}">处理</button>`:''}</td></tr>`).join('')||'<tr><td colspan="7" class="empty">暂无申请</td></tr>'}</tbody></table></div>`;}
  function renderStorage(){return pageHead('存储','原生 Cockpit 存储页面负责磁盘操作')+banner()+`<div class="grid2"><div class="card"><div class="cardhead"><h2>训练路径策略</h2></div><div class="cardbody"><p>工作目录、日志和输出必须位于本用户允许根目录。后端拒绝控制字符、非法占位符和符号链接逃逸。</p><div class="notice">本页不执行格式化、挂载或清理操作。</div></div></div><div class="card"><div class="cardhead"><h2>打开原生 Cockpit</h2></div><div class="cardbody"><a class="pf-c-button pf-m-secondary" href="/storage">存储概览 ↗</a></div></div></div>`;}
  function renderAccounts(){if(!state.identity.is_admin)return pageHead('我的账户','个人额度来自默认规则或个人覆盖')+banner()+`<div class="card"><div class="cardbody"><h2>${esc(state.identity.username)}</h2><p>GPU ${state.quota.gpu_limit}，并发 GPU ${state.quota.concurrent_gpu_limit}，活动任务 ${state.quota.active_job_limit}；来源：${esc(state.quota.source)}</p><button class="pf-c-button pf-m-secondary" data-action="apply-quota">申请长期额度调整</button></div></div>`;return pageHead('账户与配额','管理员可编辑默认额度和个人覆盖，保存前必须预览影响')+banner()+`<div class="card"><div class="cardhead"><h2>当前默认额度</h2><button class="pf-c-button pf-m-secondary" data-action="edit-default">编辑并预览</button></div><div class="cardbody"><p>GPU ${state.quota.gpu_limit} · 并发 GPU ${state.quota.concurrent_gpu_limit} · 活动任务 ${state.quota.active_job_limit}</p><div class="notice">实际账户清单和 UID 由后端读取；此页面不允许前端伪造用户身份。</div></div></div>`;}
  function renderMetrics(){const m=state.metrics||{};return pageHead('性能监控','与 GPU、队列和账户共用当前状态')+banner()+`<div class="grid3"><div class="card"><div class="cardbody"><h2>CPU 负载</h2><div class="statvalue">${m.cpu_load_1m==null?'—':m.cpu_load_1m}</div><div class="small">/proc 实测，更新时间 ${fmt(m.observed_at)}</div></div></div><div class="card"><div class="cardbody"><h2>内存</h2><div class="statvalue">${m.memory_available_mb==null?'—':m.memory_available_mb+' MiB 可用'}</div><div class="small">总量 ${m.memory_total_mb==null?'—':m.memory_total_mb+' MiB'}</div></div></div><div class="card"><div class="cardbody"><h2>GPU</h2><div class="statvalue">${m.gpu&&m.gpu.available?m.gpu.devices.length:'—'}</div><div class="small">不使用固定繁忙趋势</div></div></div></div><div class="card" style="margin-top:18px"><div class="cardbody"><h2>监控来源</h2><p>详细图表可接入 Grafana；此插件只显示当前后端采集的值。数据不可用、过期或断开时保留“—”和更新时间。</p></div></div>`;}
  function renderLogs(){return pageHead('系统日志','原生 Cockpit 日志入口；训练日志仍按作业所有权读取')+banner()+`<div class="card"><div class="cardbody"><a class="pf-c-button pf-m-secondary" href="/system/logs">打开 Cockpit 系统日志 ↗</a><pre class="audit" style="margin-top:18px">${esc(state.scheduler_available?'训练后端已连接；请从任务详情读取作业日志。':'当前没有 Slurm 服务，未读取或伪造服务日志。')}</pre></div></div>`;}
  function renderRules(){if(!state.identity.is_admin)return pageHead('调度规则','管理员可见')+`<div class="notice warn">当前会话没有管理员组权限。</div>`;return pageHead('调度规则','单作业时限与用户总配额分开；预览会列出每个受影响 JobID')+banner()+`<div class="card"><div class="panelbody"><div class="formgrid">${['debug','normal','long'].map(k=>`<div class="field"><label>${k} 单作业最长分钟</label><input class="control rule-input" data-rule="${k}" type="number" min="1" value="${state.rules[k].max_minutes}"></div>`).join('')}</div><div class="notice">应用规则不会自动终止现有任务；运行用量、活动任务、GPU 请求和“单作业超过上限”都会进入预览差异。</div><button class="pf-c-button pf-m-primary" data-action="preview-rules">预览规则影响</button><div id="rule-preview"></div></div></div>`;}
  function modal(title, body, footer='') { const root=$('#overlay');root.innerHTML=`<div class="modal-backdrop"></div><section class="modal" role="dialog" aria-modal="true"><div class="modalhead"><h2>${title}</h2><button class="close" data-close>×</button></div><div class="modalbody">${body}</div>${footer?`<div class="modalfoot">${footer}</div>`:''}</section>`;$('.modal-backdrop').onclick=closeModal;}
  function closeModal(){ $('#overlay').innerHTML=''; }
  function submitModal(){ const q=state.quota;modal('提交训练任务',`<div class="notice">权限/额度摘要：GPU ${q.gpu_limit} · 并发 GPU ${q.concurrent_gpu_limit} · 活动任务 ${q.active_job_limit}（${q.source==='personal_override'?'个人覆盖':'继承默认'}）。GPU、CPU、内存、档位和路径由后端再次校验。</div><form id="job-form"><div class="formgrid"><div class="field"><label>任务名称</label><input class="control" name="name" value="training" required pattern="[A-Za-z0-9_.-]+"></div><div class="field"><label>GPU 数量</label><input class="control" name="gpu" type="number" min="1" value="1" required></div><div class="field"><label>工作目录</label><input class="control" name="workdir" value="/home/${esc(state.identity.username)}/train" required></div><div class="field"><label>Python / Conda 环境</label><input class="control" name="environment" value="system" required></div><div class="field"><label>输出/日志路径</label><input class="control" name="output_path" value="/home/${esc(state.identity.username)}/train/slurm-%j.out" required><div class="help">仅允许一个 %j，目录须在用户允许根下。</div></div><div class="field"><label>档位</label><select class="control" name="qos">${Object.keys(state.rules).map(k=>`<option value="${k}">${k} · ${state.rules[k].max_minutes} 分钟</option>`).join('')}</select></div><div class="field"><label>CPU</label><input class="control" name="cpu" type="number" min="1" value="8" required></div><div class="field"><label>内存 MiB</label><input class="control" name="memory_mb" type="number" min="128" value="8192" required></div><div class="field"><label>实际时限（分钟）</label><input class="control" name="time_minutes" type="number" min="1" value="60" required></div></div><div class="field"><label>训练命令</label><textarea class="control" name="command" required>python train.py</textarea><div class="help">命令作为用户自己的 Slurm 作业执行；管理员后端不执行用户命令。</div></div><div id="job-error"></div></form>`,`<button class="pf-c-button pf-m-secondary" data-close>取消</button><button class="pf-c-button pf-m-primary" id="submit-job">校验并提交</button>`);$('#submit-job').onclick=async()=>{const f=$('#job-form');if(!f.reportValidity())return;const p=Object.fromEntries(new FormData(f));try{const out=await api('POST','/api/v1/jobs',p);closeModal();await refresh();showToast(out.job.state==='WAITING_QUOTA'?'已排入用户额度等待队列':'已交给调度器队列');}catch(e){$('#job-error').innerHTML=`<div class="error">${esc(failText(e))}</div>`;}};}
  function applicationModal(kind){const temp=kind==='temporary_job';modal(temp?'申请临时单作业资源':'申请长期个人额度',`<form id="app-form"><div class="formgrid">${temp?'<div class="field"><label>GPU</label><input class="control" name="gpu" type="number" min="1" value="2" required></div><div class="field"><label>档位</label><select class="control" name="qos"><option>debug</option><option selected>normal</option><option>long</option></select></div><div class="field"><label>实际时限（分钟）</label><input class="control" name="time_minutes" type="number" min="1" value="120" required></div>':'<div class="field"><label>GPU 上限</label><input class="control" name="gpu_limit" type="number" min="1" value="4" required></div><div class="field"><label>并发 GPU 上限</label><input class="control" name="concurrent_gpu_limit" type="number" min="1" value="4" required></div><div class="field"><label>活动任务上限</label><input class="control" name="active_job_limit" type="number" min="1" value="4" required></div>'}</div><div class="field"><label>申请理由</label><textarea class="control" name="reason" minlength="5" required></textarea></div><div id="app-error"></div></form>`,`<button class="pf-c-button pf-m-secondary" data-close>取消</button><button class="pf-c-button pf-m-primary" id="send-app">提交申请</button>`);$('#send-app').onclick=async()=>{const f=$('#app-form');if(!f.reportValidity())return;const x=Object.fromEntries(new FormData(f));const requested=temp?{gpu:+x.gpu,qos:x.qos,time_minutes:+x.time_minutes}:{gpu_limit:+x.gpu_limit,concurrent_gpu_limit:+x.concurrent_gpu_limit,active_job_limit:+x.active_job_limit};try{await api('POST','/api/v1/applications',{kind,requested,reason:x.reason});closeModal();await refresh();showToast('申请已保存；管理员可在申请审批中处理');}catch(e){$('#app-error').innerHTML=`<div class="error">${esc(failText(e))}</div>`;}};}
  function approveModal(id){modal('处理申请',`<form id="decision-form"><div class="notice">批准仍需等待资源；临时批准只绑定申请中的用户/GPU/档位/时限，过期不杀已启动任务。</div><div class="field"><label>动作</label><select class="control" name="action"><option value="approve">批准</option><option value="approve_adjusted">调整后批准</option><option value="reject">拒绝</option></select></div><div class="field"><label>决定理由（拒绝必填）</label><textarea class="control" name="decision_reason" required></textarea></div><div class="field"><label>临时授权有效分钟（长期额度不使用）</label><input class="control" name="valid_minutes" type="number" min="1" value="1440"></div><div id="decision-error"></div></form>`,`<button class="pf-c-button pf-m-secondary" data-close>取消</button><button class="pf-c-button pf-m-primary" id="decide">保存决定</button>`);$('#decide').onclick=async()=>{const f=$('#decision-form');if(!f.reportValidity())return;const p=Object.fromEntries(new FormData(f));try{await api('POST','/api/v1/applications/'+id+'/decision',p);closeModal();await refresh();showToast('申请状态已更新');}catch(e){$('#decision-error').innerHTML=`<div class="error">${esc(failText(e))}</div>`;}};}
  function bind(){document.querySelectorAll('[data-page]').forEach(b=>b.onclick=()=>{page=b.dataset.page;tab=page==='training'?'queue':tab;render();});document.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>{tab=b.dataset.tab;render();});document.querySelectorAll('[data-action="submit"]').forEach(b=>b.onclick=submitModal);document.querySelectorAll('[data-action="apply-temp"]').forEach(b=>b.onclick=()=>applicationModal('temporary_job'));document.querySelectorAll('[data-action="apply-quota"]').forEach(b=>b.onclick=()=>applicationModal('quota_change'));document.querySelectorAll('[data-approve]').forEach(b=>b.onclick=()=>approveModal(b.dataset.approve));document.querySelectorAll('[data-cancel]').forEach(b=>b.onclick=async()=>{try{await api('POST','/api/v1/jobs/'+b.dataset.cancel+'/cancel');await refresh();showToast('取消请求已记录');}catch(e){showToast(failText(e),'error');}});document.querySelectorAll('[data-log]').forEach(b=>b.onclick=async()=>{try{const x=await api('GET','/api/v1/jobs/'+b.dataset.log+'/log');modal('作业日志',`<div class="small mono">${esc(x.path)}</div><pre class="audit">${esc(x.available?x.content:x.reason)}</pre>`,'<button class="pf-c-button pf-m-secondary" data-close>关闭</button>');}catch(e){showToast(failText(e),'error');}});document.querySelectorAll('[data-close]').forEach(b=>b.onclick=closeModal);const pr=$('[data-action="preview-rules"]');if(pr)pr.onclick=previewRules;const ed=$('[data-action="edit-default"]');if(ed)ed.onclick=editDefault;}
  async function previewRules(){const rules={};document.querySelectorAll('.rule-input').forEach(i=>rules[i.dataset.rule]={max_minutes:+i.value});try{const p=await api('POST','/api/v1/rules/preview',{rules});$('#rule-preview').innerHTML=`<div class="success">预览已保存。${p.impacts.length?'发现 '+p.impacts.length+' 项影响：':''}</div><div class="diff">${p.impacts.map(x=>esc(x.job_id)+' · '+esc(x.user)+'：'+esc(x.reasons.join('、'))).join('<br>')||'没有发现受影响的待运行任务'}<br><button class="pf-c-button pf-m-primary" id="apply-rules">返回并应用此预览</button></div>`;$('#apply-rules').onclick=async()=>{try{await api('POST','/api/v1/rules/apply',{preview_id:p.preview_id,rules});await refresh();showToast('规则已保存；现有任务未被终止');}catch(e){showToast(failText(e),'error');}};}catch(e){showToast(failText(e),'error');}}
  function editDefault(){modal('编辑默认配额',`<form id="quota-form"><div class="formgrid"><div class="field"><label>GPU 总额</label><input class="control" name="gpu_limit" type="number" min="1" value="${state.quota.gpu_limit}"></div><div class="field"><label>并发 GPU</label><input class="control" name="concurrent_gpu_limit" type="number" min="1" value="${state.quota.concurrent_gpu_limit}"></div><div class="field"><label>活动任务</label><input class="control" name="active_job_limit" type="number" min="1" value="${state.quota.active_job_limit}"></div></div><p class="help">先预览每个待运行任务的 GPU、用量、活动数和单作业时限影响；返回编辑时输入保存在当前对话框，关闭会丢弃。</p></form>`,`<button class="pf-c-button pf-m-secondary" data-close>取消</button><button class="pf-c-button pf-m-primary" id="preview-quota">预览</button>`);$('#preview-quota').onclick=async()=>{const f=$('#quota-form'),q=Object.fromEntries(new FormData(f));try{const p=await api('POST','/api/v1/quotas/preview',{scope:'default',quota:{gpu_limit:+q.gpu_limit,concurrent_gpu_limit:+q.concurrent_gpu_limit,active_job_limit:+q.active_job_limit}});$('.modalbody').innerHTML+=`<div class="success">预览前后差异已保留。</div><div class="diff">${p.impacts.length?p.impacts.map(x=>esc(x.job_id)+'：'+esc(x.reasons.join('、'))).join('<br>'):'没有发现影响'}<br><button class="pf-c-button pf-m-primary" id="apply-quota">返回并应用</button></div>`;$('#apply-quota').onclick=async()=>{try{await api('POST','/api/v1/quotas/apply',{preview_id:p.preview_id});closeModal();await refresh();showToast('默认配额已保存');}catch(e){showToast(failText(e),'error');}};}catch(e){showToast(failText(e),'error');}};}
  async function refresh(){try{state=await api('GET','/api/v1/state');state.observed_at=state.observed_at||now();render();}catch(e){showToast(failText(e),'error');}}
  function enter(role){demoRole=role;state=loadDemo();state.identity=role==='admin'?{uid:1000,username:'u20',is_admin:true,is_training_user:true}:{uid:1001,username:'timzhang',is_admin:false,is_training_user:true};if(role==='admin')state.quota={gpu_limit:4,concurrent_gpu_limit:4,active_job_limit:4,source:'default'};$('#login').hidden=true;$('#app').hidden=false;render();}
  function logout(){if(isCockpit&&cockpit.logout){cockpit.logout();return;}$('#app').hidden=true;$('#login').hidden=false;}
  $('#logout').onclick=logout;$('#notifications').onclick=()=>{const n=(state.notifications||[]).find(x=>!x.read_at);if(n)api('POST','/api/v1/notifications/'+n.id+'/read').then(refresh);page='applications';render();};
  if(isCockpit){$('#demo-login').hidden=true;$('#cockpit-login').hidden=true;$('#login').hidden=true;$('#app').hidden=false;refresh();}else{$('#demo-enter').onclick=()=>enter($('#demo-identity').value);$('#login').hidden=false;}
})();
